mapper.insert:
INSERT INTO workflow_version (
    workflow_definition_id, version_number, status,
    metadata_json, published_at, created_at, updated_at
) VALUES (
    #{workflowDefinitionId}, #{versionNumber}, #{status},
    #{metadataJson}, #{publishedAt}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT COALESCE(MAX(version_number), 0) + 1
FROM workflow_version
WHERE workflow_definition_id = #{workflowDefinitionId}

mapper.update:
UPDATE workflow_version
SET metadata_json = #{metadataJson},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND workflow_definition_id = #{workflowDefinitionId}
  AND status = 'DRAFT'

UPDATE workflow_version
SET status = 'PUBLISHED',
    published_at = #{now},
    updated_at = #{now}
WHERE id = #{id}
  AND workflow_definition_id = #{workflowDefinitionId}
  AND status = 'DRAFT'

UPDATE workflow_version
SET status = 'DISABLED',
    updated_at = #{now}
WHERE workflow_definition_id = #{workflowDefinitionId}
  AND status = 'DRAFT'
